package proxy

import scala.concurrent.{Future, ExecutionContext, Promise}
import scala.concurrent.duration._
import scala.util.{Success, Failure, Try}
import java.nio.ByteBuffer
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

object AuthProxy {
  implicit val ec: ExecutionContext = ExecutionContext.global

  private val SECRET_KEY = sys.env.getOrElse("PROXY_SECRET", "default-secret-key-32bytes!!!!!")
  private val TOKEN_VALIDITY_MS = 300000L // 5 minutes

  case class ProxyRequest(targetHost: String, targetPort: Int, payload: Array[Byte], authToken: String)
  case class AuthResult(valid: Boolean, userId: String, permissions: Set[String])

  // Token format: base64(userId:timestamp:permissions):hmac
  def validateToken(token: String): Future[AuthResult] = Future {
    try {
      val parts = token.split(":hmac:")
      if (parts.length != 2) {
        AuthResult(false, "", Set.empty)
      } else {
        val payload = parts(0)
        val providedHmac = parts(1)
        val expectedHmac = computeHmac(payload)

        if (constantTimeEquals(expectedHmac, providedHmac)) {
          val decoded = new String(java.util.Base64.getDecoder.decode(payload))
          val fields = decoded.split(":")
          if (fields.length >= 3) {
            val userId = fields(0)
            val timestamp = fields(1).toLong
            val permissions = fields.drop(2).toSet
            val now = System.currentTimeMillis()
            if (now - timestamp < TOKEN_VALIDITY_MS) {
              AuthResult(true, userId, permissions)
            } else {
              AuthResult(false, userId, Set.empty)
            }
          } else {
            AuthResult(false, "", Set.empty)
          }
        } else {
          AuthResult(false, "", Set.empty)
        }
      }
    } catch {
      case _: Exception => AuthResult(false, "", Set.empty)
    }
  }

  private def computeHmac(data: String): String = {
    val mac = Mac.getInstance("HmacSHA256")
    val keySpec = new SecretKeySpec(SECRET_KEY.getBytes("UTF-8"), "HmacSHA256")
    mac.init(keySpec)
    val rawHmac = mac.doFinal(data.getBytes("UTF-8"))
    rawHmac.map("%02x".format(_)).mkString
  }

  // Constant-time comparison to prevent timing attacks
  private def constantTimeEquals(a: String, b: String): Boolean = {
    if (a.length != b.length) return false
    var result = 0
    val aBytes = a.getBytes("UTF-8")
    val bBytes = b.getBytes("UTF-8")
    for (i <- aBytes.indices) {
      result |= (aBytes(i) ^ bBytes(i))
    }
    result == 0
  }

  case class RateLimitState(count: Int, windowStart: Long)
  private val rateLimits = new java.util.concurrent.ConcurrentHashMap[String, RateLimitState]()
  private val MAX_REQUESTS_PER_WINDOW = 100
  private val WINDOW_SIZE_MS = 60000L

  def checkRateLimit(userId: String): Future[Boolean] = Future {
    val now = System.currentTimeMillis()
    val state = rateLimits.compute(userId, (_, existing) => {
      if (existing == null || now - existing.windowStart > WINDOW_SIZE_MS) {
        RateLimitState(1, now)
      } else {
        RateLimitState(existing.count + 1, existing.windowStart)
      }
    })
    state.count <= MAX_REQUESTS_PER_WINDOW
  }

  private val allowedHosts = Set("api.internal.corp", "db.internal.corp", "cache.internal.corp")

  def validateDestination(host: String, permissions: Set[String]): Future[Boolean] = Future {
    val hostAllowed = allowedHosts.contains(host)
    val hasPermission = permissions.exists(p => host.startsWith(p.replace("access:", "")))
    hostAllowed && hasPermission
  }

  def handleRequest(request: ProxyRequest): Future[Either[String, Array[Byte]]] = {
    val authFuture = validateToken(request.authToken)

    authFuture.flatMap {
      case AuthResult(false, _, _) => 
        Future.successful(Left("Authentication failed"))
      case AuthResult(true, userId, permissions) =>
        checkRateLimit(userId).flatMap {
          case false => Future.successful(Left("Rate limit exceeded"))
          case true =>
            validateDestination(request.targetHost, permissions).flatMap {
              case false => Future.successful(Left("Destination not allowed"))
              case true => forwardRequest(request)
            }
        }
    }
  }

  private def forwardRequest(request: ProxyRequest): Future[Either[String, Array[Byte]]] = Future {
    // Simulated forwarding - in production this would open a socket
    Right(s"Forwarded ${request.payload.length} bytes to ${request.targetHost}:${request.targetPort}".getBytes)
  }

  // Connection pool management with async cleanup
  private case class PooledConnection(host: String, port: Int, createdAt: Long, lastUsed: Long)
  private val connectionPool = new java.util.concurrent.ConcurrentHashMap[String, PooledConnection]()

  def getOrCreateConnection(host: String, port: Int): Future[PooledConnection] = Future {
    val key = s"$host:$port"
    connectionPool.compute(key, (_, existing) => {
      val now = System.currentTimeMillis()
      if (existing == null || now - existing.lastUsed > 30000L) {
        PooledConnection(host, port, now, now)
      } else {
        existing.copy(lastUsed = now)
      }
    })
  }
}
